mapper.select:
SELECT o.*, c.customer_name, w.warehouse_name, u1.real_name as salesman_name, u2.real_name as approver_name, d.dept_name FROM biz_sale_order o LEFT JOIN biz_customer c ON o.customer_id = c.id LEFT JOIN biz_warehouse w ON o.warehouse_id = w.id LEFT JOIN sys_user u1 ON o.salesman_id = u1.id LEFT JOIN sys_user u2 ON o.approver_id = u2.id LEFT JOIN sys_dept d ON o.dept_id = d.id WHERE o.deleted = 0
AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND o.customer_id = #{customerId}
AND o.status = #{status}
AND o.dept_id = #{deptId}
ORDER BY o.create_time DESC
